import fs from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';
import {SETDA_PARTS} from '../functions/_lib/setda.js';
const html=fs.readFileSync(new URL('../public/index.html',import.meta.url),'utf8');
for(const id of ['btnSetdaPartsNav','setdaDashboardPanel','pemdaSetdaPanel','pemdaSetdaSummary','pemdaSetdaGrid','pemdaSetdaOpen'])assert.ok(html.includes(`id="${id}"`),`UI must contain ${id}`);
const el=new Map();
const get=id=>{if(!el.has(id))el.set(id,{id,innerHTML:'',textContent:'',hidden:false,disabled:false,style:{display:'none'},open:false,addEventListener(){},showModal(){this.open=true},close(){this.open=false}});return el.get(id)};
const data={status:'success',enabled:true,accountSummary:{active:9,disabled:0,missing:0,total:9},parts:SETDA_PARTS.map((p,i)=>({...p,id:`setda_bagian_2026_${p.code}`,username:p.username,accountStatus:'aktif',items:i,evidence:i+1,workbookUrl:''})),items:[],evidence:[]};
const sandbox={console,document:{getElementById:get,hidden:false},currentUser:{username:'admin_daerah',role:'admin',opdName:null},currentYear:'2026',rows:[],setInterval(){},callServer:async()=>data};
vm.createContext(sandbox);
vm.runInContext(fs.readFileSync(new URL('../public/setda.js',import.meta.url),'utf8'),sandbox);
vm.runInContext('renderSetdaEntry()',sandbox);
assert.equal(get('btnSetdaPartsNav').style.display,'inline-flex');
assert.equal(get('setdaDashboardPanel').hidden,false);
await vm.runInContext('loadPemdaSetdaPanel()',sandbox);
assert.equal((get('pemdaSetdaGrid').innerHTML.match(/<article>/g)||[]).length,9);
assert.ok(get('pemdaSetdaSummary').textContent.includes('9 dari 9 akun aktif'));
sandbox.currentUser={username:'opd_setda',role:'opd',opdName:'SEKRETARIAT DAERAH'};
vm.runInContext('renderSetdaEntry()',sandbox);assert.equal(get('pemdaSetdaPanel').hidden,false);
sandbox.currentUser={username:'opd_lain',role:'opd',opdName:'SEKRETARIAT DPRD'};
vm.runInContext('renderSetdaEntry()',sandbox);assert.equal(get('btnSetdaPartsNav').style.display,'none');assert.equal(get('pemdaSetdaPanel').hidden,true);
console.log('PASS: 9 bagian muncul pada dashboard Pemda dan navigasi; akun induk Setda dapat melihat; OPD lain tidak melihat; tidak menambah baris 28 OPD utama.');
